                ConfigureCanvas(canvas,camera);AssertCanvasChannels(canvas,camera,pass,spec.File,"baseline",0);
                var oracle=Oracle.Make(spec);ConfigureRootForTarget(rootRect,backdrop,spec.Width,spec.Height);ApplyOracle(safe,oracle);AssertAuthoringView(root);AssertLayout(root,canvas,camera,rootRect,backdrop,safe,oracle);
                target=NewRt(spec.Width,spec.Height);ConfigureCamera(camera,target,spec.Width,spec.Height);
                Canvas.ForceUpdateCanvases();foreach(var text in root.GetComponentsInChildren<TMP_Text>(true))text.ForceMeshUpdate(true,true);Canvas.ForceUpdateCanvases();AssertCanvasChannels(canvas,camera,pass,spec.File,"after-tmp",RequiredCanvasChannelMask);AssertTmp(root);
                AssertCanvasChannels(canvas,camera,pass,spec.File,"render",RequiredCanvasChannelMask);RenderTexture.active=target;GL.sRGBWrite=true;camera.Render();
                readback=new Texture2D(spec.Width,spec.Height,TextureFormat.RGBA32,false,false);readback.ReadPixels(new Rect(0,0,spec.Width,spec.Height),0,0);readback.Apply(false,false);var bytes=readback.EncodeToPNG();CheckPng(bytes,spec.Width,spec.Height,spec.File);if(persist)File.WriteAllBytes(Path.Combine(directory,spec.File),bytes);result=new Result(spec.File,oracle,bytes);
