        static bool StagePublish(string tmp,string final,string prev)
        {
            var old=Directory.Exists(final);if(old){ValidateSet(final,null);Require(SameCaptureBytes(tmp,final),"Same/fresh process capture byte drift.");}var oldMoved=false;var newMoved=false;try{if(old){Directory.Move(final,prev);oldMoved=true;}Directory.Move(tmp,final);newMoved=true;ValidateSet(final,null);return old;}catch{try{if(newMoved&&Directory.Exists(final))Directory.Move(final,tmp);if(oldMoved&&Directory.Exists(prev)&&!Directory.Exists(final))Directory.Move(prev,final);}finally{if(Directory.Exists(tmp))Directory.Delete(tmp,true);}if(old&&!Directory.Exists(final))throw new InvalidOperationException("Previous capture set rollback failed.");throw;}
        }
        static void CommitPublish(string prev){if(Directory.Exists(prev))Directory.Delete(prev,true);Require(!Directory.Exists(prev),"Capture publish retained .prev.");}
        static void RollbackPublish(string final,string prev,bool hadPreviousFinal){if(Directory.Exists(final))Directory.Delete(final,true);if(hadPreviousFinal){Require(Directory.Exists(prev),"Capture rollback lost prior final set.");Directory.Move(prev,final);ValidateSet(final,null);}else Require(!Directory.Exists(prev),"Capture rollback has unexpected prior set.");}
        static bool SameCaptureBytes(string left,string right){return Specs.Select(x=>x.File).Concat(new[]{"manifest.json"}).All(name=>File.ReadAllBytes(Path.Combine(left,name)).SequenceEqual(File.ReadAllBytes(Path.Combine(right,name))));}
        // Focused EditMode-only probe: real project TMP objects and the same exact phase predicate.
