        internal static void CanvasChannelProbeForTests(Canvas canvas,Camera camera,TMP_Text[] texts,string pass,string file,int injection)
        {
            Exception primary=null,cleanup=null;
            try
            {
                ConfigureCanvas(canvas,camera);AssertCanvasChannels(canvas,camera,pass,file,"baseline",0);
                Canvas.ForceUpdateCanvases();foreach(var text in texts)text.ForceMeshUpdate(true,true);Canvas.ForceUpdateCanvases();AssertCanvasChannels(canvas,camera,pass,file,"after-tmp",RequiredCanvasChannelMask);
                if(injection==1||injection==6)throw new InvalidOperationException("Injected after TMP.");if(injection==2)throw new InvalidOperationException("Injected before render.");AssertCanvasChannels(canvas,camera,pass,file,"render",RequiredCanvasChannelMask);if(injection==3)throw new InvalidOperationException("Injected after render.");if(injection==4)throw new InvalidOperationException("Injected readback.");
            }
            catch(Exception e){primary=e;}
            finally
